// Access widget context
var data = widgetContext.data; // Timeseries data
var timeWindow = widgetContext.timeWindow; // Time window for start/end time
var http = widgetContext.http;

function formatLocalDate(timestamp) {
    var date = new Date(timestamp);
    var year = date.getFullYear();
    var month = String(date.getMonth() + 1).padStart(2, '0');
    var day = String(date.getDate()).padStart(2, '0');
    var hours = String(date.getHours()).padStart(2, '0');
    var minutes = String(date.getMinutes()).padStart(2, '0');
    var seconds = String(date.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

// Collect unique entities with their IDs
var macIds = [];
var entityInfo = {};
data.forEach(function(ds) {
    var eName = ds.datasource.entityName;
    if (!entityInfo[eName]) {
        macIds.push(eName);
        entityInfo[eName] = {
            entityId: ds.datasource.entityId,
            entityLabel: ds.datasource.entityLabel || eName,
            deviceName: null
        };
    }
});

var startTime = new Date(timeWindow.minTime).toISOString();
var endTime = new Date(timeWindow.maxTime).toISOString();

// Fetch deviceName client attribute for each entity, then generate CSV
var pending = macIds.length;

function onAllResolved() {
    var csvContent = "data:text/csv;charset=utf-8,";

    // Build deviceNameMap: deviceName attribute -> entityLabel -> entityName
    var deviceNameMap = {};
    macIds.forEach(function(eName) {
        var info = entityInfo[eName];
        deviceNameMap[eName] = info.deviceName || info.entityLabel || eName;
    });

    var deviceNames = macIds.map(function(m) { return deviceNameMap[m]; });

    // Add metadata
    csvContent += "Device(s)," + deviceNames.join("; ") + "\n";
    csvContent += "Mac ID(s)," + macIds.join("; ") + "\n";
    csvContent += "Start Time," + startTime + "\n";
    csvContent += "End Time," + endTime + "\n";
    csvContent += "\n";

    // Create CSV headers
    var headers = ["Timestamp"];
    data.forEach(function(ds) {
        var displayName = deviceNameMap[ds.datasource.entityName] || ds.datasource.entityName;
        headers.push(displayName + " - " + ds.dataKey.label);
    });
    csvContent += headers.join(",") + "\n";

    // Process timeseries data
    var rows = {};
    data.forEach(function(ds) {
        var displayName = deviceNameMap[ds.datasource.entityName] || ds.datasource.entityName;
        ds.data.forEach(function(point) {
            var timestamp = point[0];
            var value = point[1];
            if (!rows[timestamp]) {
                rows[timestamp] = { timestamp: formatLocalDate(timestamp), values: {} };
            }
            rows[timestamp].values[displayName + " - " + ds.dataKey.label] = value;
        });
    });

    // Convert rows to CSV
    Object.keys(rows).forEach(function(timestamp) {
        var row = [rows[timestamp].timestamp];
        headers.slice(1).forEach(function(header) {
            row.push(rows[timestamp].values[header] || "");
        });
        csvContent += row.join(",") + "\n";
    });

    // Trigger CSV download
    var encodedUri = encodeURI(csvContent);
    var link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", deviceNames.join("; ") + "_current_voltage_" + startTime.split(" ")[0] + "_" + endTime.split(" ")[0] + ".csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

// Fetch deviceName attribute for each device via API
macIds.forEach(function(eName) {
    var info = entityInfo[eName];
    var url = '/api/plugins/telemetry/DEVICE/' + info.entityId + '/values/attributes/CLIENT_SCOPE?keys=deviceName';
    http.get(url).subscribe(
        function(response) {
            if (response && response.length > 0) {
                response.forEach(function(attr) {
                    if (attr.key === 'deviceName' && attr.value) {
                        info.deviceName = attr.value;
                    }
                });
            }
            pending--;
            if (pending === 0) onAllResolved();
        },
        function(error) {
            pending--;
            if (pending === 0) onAllResolved();
        }
    );
});

