    var msg = value;
    var s = String(msg == null ? '' : msg).toLowerCase();
    var hit = s.indexOf('alert') >= 0 || s.indexOf('fail') >= 0 || s.indexOf('reject') >= 0 ||
              s.indexOf('leak') >= 0 || s.indexOf('fault') >= 0 || s.indexOf('overload') >= 0 ||
