    } else if (widgetContext.subscription && typeof widgetContext.subscription.onUpdated === 'function') {
        widgetContext.subscription.onUpdated();
    } else if (widgetContext.updateTimewindow) {
        widgetContext.updateTimewindow(widgetContext.timeWindow);
    }
    if (widgetContext.detectChanges) widgetContext.detectChanges();
} catch (e) { console.error('Refresh failed', e); }

// Synchronize Logs - ask the device to resend entries in a date range.
// Uses the resendRecentLogs RPC handled by mqttCallback in firmware.
try {
    var data = widgetContext.data || [];
    var entityId = null, entityLabel = null;
    if (data.length && data[0].datasource) {
        entityId = data[0].datasource.entityId;
        entityLabel = data[0].datasource.entityLabel || data[0].datasource.entityName;
    }
    if (!entityId) { window.alert('No device selected in this widget.'); return; }

    function pad(n){ return String(n).padStart(2,'0'); }
    function todayStr(){ var d=new Date(); return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()); }
    function yestStr(){ var d=new Date(Date.now()-86400000); return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()); }

    var defFrom = yestStr();
    var defTo   = todayStr();
    var fromStr = window.prompt('Synchronize Debug Logs - From date (YYYY-MM-DD)\nDevice: ' + (entityLabel||entityId), defFrom);
    if (!fromStr) return;
    var toStr   = window.prompt('Synchronize Debug Logs - To date (YYYY-MM-DD)', defTo);
    if (!toStr) return;

    var fp = fromStr.split('-'), tp = toStr.split('-');
    if (fp.length!==3 || tp.length!==3) { window.alert('Dates must be in YYYY-MM-DD format.'); return; }
    var fromMs = new Date(+fp[0], +fp[1]-1, +fp[2], 0, 0, 0).getTime();
    var toMs   = new Date(+tp[0], +tp[1]-1, +tp[2], 23, 59, 59).getTime();
    if (isNaN(fromMs) || isNaN(toMs)) { window.alert('Invalid date.'); return; }
    if (fromMs > toMs) { window.alert('"From" must be on or before "To".'); return; }

    var http = widgetContext.http;
    if (!http) { window.alert('HTTP service unavailable in this widget.'); return; }
    http.post('/api/rpc/twoway/' + entityId, {
        method: 'resendRecentLogs',
        params: { from: Math.floor(fromMs/1000), to: Math.floor(toMs/1000), type: 'debug' },
        timeout: 10000
    }).subscribe(function(r){
        var resp = (r && r.data) ? r.data : r;
        if (resp && resp.success) {
            var n = resp.queued || 0;
            if (widgetContext.showSuccessToast) widgetContext.showSuccessToast('Queued ' + n + ' entries. Refreshing...', 3000, 'bottom', 'left', 'successToast');
            else window.alert('Queued ' + n + ' entries on device.');
            // Kick a few reloads so the backfilled rows appear without a manual refresh.
            [4000, 12000, 30000].forEach(function(t){
                setTimeout(function(){
                    try {
                        if (widgetContext.subscriptionApi && widgetContext.subscriptionApi.reload) widgetContext.subscriptionApi.reload();
                        else if (widgetContext.subscription && widgetContext.subscription.update) widgetContext.subscription.update();
                    } catch(_){}
                }, t);
            });
        } else {
            var msg = (resp && resp.message) ? resp.message : 'Device busy or not connected';
            if (widgetContext.showErrorToast) widgetContext.showErrorToast(msg, 'bottom', 'left', 'errorToast');
            else window.alert(msg);
        }
    }, function(err){
        var msg = 'Request failed (device offline?)';
        if (widgetContext.showErrorToast) widgetContext.showErrorToast(msg, 'bottom', 'left', 'errorToast');
        else window.alert(msg);
    });
} catch (e) { console.error('Synchronize Logs failed', e); window.alert('Synchronize Logs failed: ' + e.message); }

