rowClick.customFunction:
// rowClick — modifier-key aware navigation.
// $event has the original mouse event so we can detect Shift / Ctrl / Cmd.
try {
    var devId   = (entityId && entityId.id)   ? entityId.id   : entityId;
    var devType = (entityId && entityId.entityType) ? entityId.entityType : 'DEVICE';
    var stateParams = {
        device_id: { entityId: { entityType: devType, id: devId }, entityName: entityName }
    };

    var sc = widgetContext.stateController;
    var newTab = $event && ($event.shiftKey || $event.ctrlKey || $event.metaKey || $event.button === 1);

    if (newTab) {
        // Build a URL to the same dashboard with the device state pushed on top
        // of whatever state is currently encoded in the URL. The original tab
        // is left untouched, so its search box stays filled in.
        try {
            var url = new URL(window.location.href);
            var existing = [];
            var st = url.searchParams.get('state');
            if (st) {
                try { existing = JSON.parse(decodeURIComponent(escape(atob(st)))); }
                catch (_) { existing = []; }
                if (!Array.isArray(existing)) existing = [];
            }
            existing.push({ id: 'device_home', params: stateParams });
            var encoded = btoa(unescape(encodeURIComponent(JSON.stringify(existing))));
            url.searchParams.set('state', encoded);
            window.open(url.toString(), '_blank', 'noopener');
            if ($event && $event.preventDefault) $event.preventDefault();
            if ($event && $event.stopPropagation) $event.stopPropagation();
            return;
        } catch (e) {
            console.error('[Devices rowClick] new-tab build failed, falling back', e);
            // Fall through to same-tab navigation if URL construction failed.
        }
    }

    if (sc && typeof sc.openState === 'function') {
        sc.openState('device_home', stateParams);
    } else {
        console.error('[Devices rowClick] stateController.openState unavailable');
    }
} catch (e) {
    console.error('[Devices rowClick] error', e);
}
